{
  "extends": ["jason", "prettier"],
  "env": {
    "browser": true
  },
  "parserOptions": {
    "requireConfigFile": false
  },
  "rules": {
    "@typescript-eslint/no-shadow": "off",
    "@typescript-eslint/no-empty-interface": "off"
  },
  "overrides": [
    {
      "files": ["test/**"],
      "plugins": ["jest"],
      "env": {
        "jest/globals": true
      },
      "rules": {
        "global-require": "off",
        "no-await-in-loop": "off",
        "jest/no-disabled-tests": "warn",
        "jest/no-focused-tests": "error",
        "jest/no-identical-title": "error",
        "jest/prefer-to-have-length": "warn",
        "@typescript-eslint/no-empty-function": "off"
      }
    }
  ]
}

import nodeResolve from '@rollup/plugin-node-resolve';
import babel from '@rollup/plugin-babel';
import dts from 'rollup-plugin-dts';
import filesize from 'rollup-plugin-filesize';

const base = {
  input: './src/index.ts',
  plugins: [
    nodeResolve({ extensions: ['.js', '.ts'] }),
    babel({
      babelrc: true,
      envName: 'esm',
      extensions: ['.js', '.ts'],
    }),
  ],
  external: ['tiny-case', 'toposort', 'fn-name', 'property-expr'],
};

module.exports = [
  {
    input: './dts/index.d.ts',
    output: [{ file: 'lib/index.d.ts', format: 'es' }],
    plugins: [dts()],
  },
  {
    ...base,
    output: [
      {
        file: 'lib/index.js',
        format: 'cjs',
      },
      {
        file: 'lib/index.esm.js',
        format: 'es',
      },
    ],
    plugins: [...base.plugins, filesize()],
  },
];

import { defineConfig } from 'vitest/config';

export default defineConfig({
  test: {
    environment: 'node',
    setupFiles: ['./test-setup.mjs'],
    include: ['test/**/*.{js,ts}'],
    exclude: [
      'test/helpers.ts',
      'test/.eslintrc.js',
      'test/**/.eslintrc.js',
      'test/types/types.ts',
    ],
    globals: false,
    projects: [
      {
        extends: true,
        test: {
          name: 'async',
        },
        define: {
          'global.YUP_USE_SYNC': false,
        },
      },
      {
        extends: true,
        test: {
          name: 'sync',
        },
        define: {
          'global.YUP_USE_SYNC': true,
        },
      },
    ],
  },
});

module.exports = {
  parser: '@typescript-eslint/parser',
  parserOptions: {
    tsconfigRootDir: __dirname,
    project: ['../tsconfig.json'],
  },
  plugins: ['ts-expect'],
  rules: {
    'ts-expect/expect': 'error',
  },
};

{
  "extends": ["jason", "4catalyzer-typescript"]
}

{
