    "glob": "^7.2.0",
    "jsdom": "^24.1.0",
    "patch-package": "^8.0.0",
    "react": "^19.1.0",
    "react-dom": "^19.1.0",
    "react-is": "^19.1.0",
    "rollup": "^2.59.0",
    "rollup-plugin-dts": "^4.0.1",
    "sucrase": "^3.35.0",
    "typescript": "^5.4.5",
    "vitest": "^1.6.0"
  },
  "dependencies": {
    "@restart/hooks": "^0.6.2",
    "prism-react-renderer": "^2.4.1",
    "sourcemap-codec": "^1.4.8",
    "uncontrollable": "^9.0.0"
  },
  "peerDependencies": {
    "react": ">=18.3.1",
    "react-dom": ">=18.3.1",
    "react-is": ">=18.3.1"
  },
  "packageManager": "yarn@4.8.1+sha512.bc946f2a022d7a1a38adfc15b36a66a3807a67629789496c3714dd1703d2e6c6b1c69ff9ec3b43141ac7a1dd853b7685638eb0074300386a59c18df351ef8ff6",
  "resolutions": {
    "@4c/rollout@npm:^3.0.1": "patch:@4c/rollout@npm%3A3.0.1#~/.yarn/patches/@4c-rollout-npm-3.0.1-04c0733bf4.patch"
  }
}

import resolve from '@rollup/plugin-node-resolve';
import commonjs from '@rollup/plugin-commonjs';

export default [
  {
    input: 'vendor/sucrase.js',
    output: {
      file: 'src/transform/parser.js',
      format: 'es',
    },
    plugins: [
      resolve(), // so Rollup can find `ms`
      commonjs(), // so Rollup can convert `ms` to an ES module
    ],
  },
];

import { defineConfig } from 'vitest/config';

export default defineConfig({
  test: {
    environment: 'jsdom',
    setupFiles: './test/setup.ts',
    // TODO: remove include prop after complete Vitest migration
    include: ['test/**/*.{test,spec}.?(c|m)[jt]s?(x)'],
  },
});

import { resolve } from 'path';

import { defineConfig } from 'vitest/config';

export default defineConfig({
  test: {
    dir: resolve('./test'),
    globals: true,
    setupFiles: ['./test/setup.ts'],
    environment: 'jsdom',
  },
});

const path = require('path');

console.log(path.resolve('../src'));
module.exports = {
  extends: '../.eslintrc.yml',
  rules: {
    'react/prop-types': 'off',
  },
  settings: {
    'import/extensions': ['.js', '.ts', '.tsx'],
    'import/resolver': {
      node: {},
      webpack: {
        config: {
          resolve: {
            symlinks: false,
            extensions: ['.js', '.ts', '.tsx'],
            alias: {
              'react-formal': path.resolve('../src'),
            },
          },
        },
      },
    },
  },
};

const { transparentize } = require('polished');

module.exports = {
