    colors: {
      'gray': {
        50: '#fafafa',
        100: '#ededee',
        200: '#e0e1e2',
        300: '#d2d3d4',
        400: '#c3c4c6',
        500: '#b2b3b5',
        600: '#9ea0a3',
        700: '#87898d',
        800: '#6a6c71',
        900: '#3d3f45',
      },
